/**
 * Settings change broadcast.
 *
 * The worker (agent-server-stdio) keeps its own SettingsManager
 * instance; without an explicit reload it ignores edits the user
 * makes through the settings page. The "codeshell:settings-changed"
 * event is App.tsx's signal to dispatch configure({reloadModels:
 * true}) at the worker. Every successful settings write must fire
 * the event — historically callers forgot, which is exactly the
 * "project-level settings 不生效" bug from TODO-week.md #3.
 *
 * This helper centralises the dispatch so call sites just go through
 * `writeSettings(...)` and don't have to remember.
 */

export function notifySettingsChanged(): void {
  window.dispatchEvent(new Event("codeshell:settings-changed"));
}

export async function writeSettings(
  scope: "user" | "project",
  patch: Record<string, unknown>,
  projectPath?: string,
): Promise<void> {
  await updateScopedSettings(scope, patch, projectPath);
  notifySettingsChanged();
}

export async function writeSettings(
  scope: SettingsScope,
  patch: Record<string, unknown>,
  projectPath?: string,
): Promise<void> {
  if (!isPlainRecord(patch)) throw new Error("settings patch must be a plain object");
  assertSafePatch(patch);
  const p = resolveSettingsPath(scope, projectPath);
  // Serialize per file. Tail off the previous write (ignoring its rejection so
  // one failure doesn't poison the chain) before doing our read-modify-write.
  const prev = writeChains.get(p) ?? Promise.resolve();
  const next = prev
    .catch(() => {})
    .then(() => {
      // Cross-process lock around the whole RMW. Lock the dir, not the file.
      // Keep the operation synchronous: other stores in this same process
      // also synchronously take this directory lock and must not block an
      // async holder's continuation until it is mistaken for a stale owner.
      const release = acquireFileLock(p);
      try {
        const current = readSettingsForMutation(p) ?? {};
        const merged = deepMerge(current, patch);
        normalizeWorktreeBranchPrefixIfPatched(patch, merged);
        // Unique temp name so a concurrent writer for the same file can't clobber
        // our half-written temp and produce corrupt JSON after rename.
        writeSettingsFileAtomic(p, merged);
      } finally {
        release();
      }
    });
  writeChains.set(p, next);

function deepMerge(
  a: Record<string, unknown>,
  b: Record<string, unknown>,
): Record<string, unknown> {
  const out: Record<string, unknown> = { ...a };
  for (const [k, v] of Object.entries(b)) {
    if (v === null) {
      delete out[k];
    } else if (
      v &&
      typeof v === "object" &&
      !Array.isArray(v) &&
      typeof out[k] === "object" &&
      out[k] !== null &&
      !Array.isArray(out[k])
    ) {
      out[k] = deepMerge(out[k] as Record<string, unknown>, v as Record<string, unknown>);
    } else {
      out[k] = stripNulls(v);
    }
  }
  return out;
}

/** Drop null-valued keys from a plain object recursively; other values pass through. */
function stripNulls(value: unknown): unknown {
  if (!value || typeof value !== "object" || Array.isArray(value)) return value;
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
    if (FORBIDDEN_SETTING_KEYS.has(k)) continue;
    if (v === null) continue;
    out[k] = stripNulls(v);
  }
  return out;
}

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

