/**
 * Reconcile user-supplied compaction ratios into a safe ordering.
 *
 * The three tiers must satisfy `floor < compact < summarize` or the manager
 * fires them in the wrong order (e.g. an emergency window-compact before the
 * cheaper summary). Users edit these freely in settings.json, so we clamp
 * rather than trust: summarize is pulled up to at least compact, floor is
 * pushed down to at most compact. Absent fields are left undefined so the
 * ContextManager keeps its own default for them.
 */
export function clampContextRatios(input: {
  compactAtRatio?: number;
  summarizeAtRatio?: number;
  microcompactFloorRatio?: number;
}): {
  compactAtRatio?: number;
  summarizeAtRatio?: number;
  microcompactFloorRatio?: number;
} {
  const compact = input.compactAtRatio;
  const summarize =
    input.summarizeAtRatio !== undefined && compact !== undefined
      ? Math.max(input.summarizeAtRatio, compact)
      : input.summarizeAtRatio;
  const floor =
    input.microcompactFloorRatio !== undefined && compact !== undefined
      ? Math.min(input.microcompactFloorRatio, compact)
      : input.microcompactFloorRatio;
  return {
    compactAtRatio: compact,
    summarizeAtRatio: summarize,
    microcompactFloorRatio: floor,
  };
}

  // 0.85 ≈ effectiveContextWindow − reserved-output buffer (CC's
  // autoCompactThreshold pattern: window − 13k buffer − 20k output budget
  // ≈ 0.83 on a 200k window, 0.97 on 1M). 0.6 was wasting 40% of any model
  // with a window over ~150k.
  maxTokens: 200_000,
  compactAtRatio: 0.85,
  summarizeAtRatio: 0.92,
  maxToolResultChars: 30_000,
  toolOutputTokenLimit: DEFAULT_TOOL_OUTPUT_TOKEN_LIMIT,
  toolMessageTokenLimit: DEFAULT_TOOL_MESSAGE_TOKEN_LIMIT,
  // 0.7 leaves micro idle until the prompt is ~70% full. Below this we
  // let tool_results stay intact: under-pressure context doesn't need
  // micro and wiping early Read/Bash output just forces the model to
  // re-fetch the same files later. CC's external path triggers around
  // 70-75% of the window; this matches it. Was 0.5 — on a 200k model
  // that fired at 100k where a long-but-not-overloaded conversation
  // (~130k tokens) tripped micro every single turn, with the cleared
  // 8 rounds promptly replaced by 5 fresh ones so the next turn was
  // back at 130k and the cycle repeated. 0.7 → 140k floor, leaving
  // realistic headroom before we start churning.
  microcompactFloorRatio: 0.7,
};

}

